    "en": "Lucius Aelius Sejanus",
    "life": "约前20—公元31年",
    "relation": "提比略的禁卫军长官",
    "place": "rome",
    "bio": "骑士出身，替提比略管着京城和禁卫军，被皇帝称作“我的劳作伙伴”；想当接班人，31年被处死。",
