    "en": "Tiberius",
    "life": "前42—公元37年",
    "relation": "奥古斯都的继子和养子 · 尤利娅的第三任丈夫",
    "place": "rome",
    "bio": "能打仗的贵族，讨厌奉承。塔西佗说，他每次走出元老院，都要用希腊语念叨一句：“这些人，多么甘心当奴才！”",
