    "name": "克劳狄乌斯",
    "en": "Claudius",
    "life": "前10—公元54年",
    "relation": "提比略的侄子 · 卡利古拉的叔叔",
    "place": "lugdunum",
    "bio": "生在卢格杜努姆，从小跛足口吃，被家里当成笑话，躲进书房写史书；五十岁被禁卫军抬上皇位。",
