    "life": "37—68年",
    "relation": "奥古斯都的后代 · 克劳狄乌斯的继子",
    "place": "rome",
    "bio": "古人说，母亲小阿格里皮娜为他毒死了克劳狄乌斯；他后来又杀了母亲。爱唱歌、赛车，在希腊巡回比赛拿了一千八百多顶桂冠。",
