    "en": "Seneca the Younger",
    "life": "约前4—公元65年",
    "relation": "尼禄的老师和谋臣 · 斯多葛派哲学家",
    "place": "rome",
    "bio": "生在西班牙的科尔杜巴，道德文章和书信流传至今；当谋臣时攒下巨富，常被人讥为言行不一。",
