    "en": "Pertinax",
    "life": "126—193年",
    "relation": "释奴之子 · 马可·奥勒留提拔的将领",
    "place": "albapompeia",
    "bio": "父亲是做木材生意的释奴，说自己做买卖“顽强”（pertinacia），就给儿子取名佩蒂纳克斯。他先当文法教师，嫌挣得少才去从军。",
