    "en": "Hadrian",
    "life": "76—138年",
    "relation": "图拉真的表侄、养子 · 萨比娜的丈夫",
    "place": "italica",
    "bio": "留全脸胡子的头一个皇帝，人称“小希腊人”。临终写了一首小诗：“小灵魂，飘忽的，可爱的，身体的客人和伙伴，如今你要往哪里去？”",
