    "name": "卡拉卡拉",
    "en": "Caracalla",
    "life": "188—217年",
    "relation": "塞维鲁的长子 · 尤利娅·多姆娜的儿子",
    "place": "lugdunum",
    "bio": "本名巴西亚努斯，“卡拉卡拉”是他爱穿的一种高卢连帽长袍。他崇拜亚历山大，用据说是亚历山大用过的兵器和杯子，还编了一支一万六千人的“亚历山大方阵”。",
