    "en": "Arius",
    "life": "约256—336年",
    "relation": "亚历山大里亚的长老",
    "place": "alexandria",
    "bio": "利比亚人，讲道有名。他说圣子是被造的，“曾有一时没有他”；还把道理编成小曲，给水手、磨坊工和赶路的人唱。",
