    "en": "Athanasius",
    "life": "约296—373年",
    "relation": "亚历山大里亚主教 · 尼西亚信经的旗手",
    "place": "alexandria",
    "bio": "尼西亚会上还是主教亚历山大的执事，328年接任主教。一生五次被流放，后人说他是“阿塔纳修斯对抗全世界”。",
