    "en": "Crispus",
    "life": "约300—326年",
    "relation": "君士坦丁的长子 · 拉克坦提乌斯的学生",
    "place": "treveri",
    "bio": "母亲米涅尔维娜，拉丁史书说是君士坦丁的情人。317年立为副皇帝，驻特里尔守莱茵河，老师是写《论迫害者之死》的拉克坦提乌斯。",
