    "bio": "他在全国大修神庙、厚待祭司，百姓奉他为“神鹰”。兵败后逃往上埃及、再到努比亚，下落不明。后来流传的《亚历山大传奇》，说他逃到马其顿，成了亚历山大的生父。",
