    "bio": "据希罗多德，他是米底王弗拉欧尔特斯之子，父亲死于和亚述的战争。他把扎格罗斯山里的米底部落拢成一国，联合巴比伦灭了亚述，与吕底亚打成平手，前585年讲和后不久去世，王位传给儿子阿斯提阿格斯。",
