    "bio": "安善王冈比西斯一世之子，据希罗多德，母亲是米底王阿斯提阿格斯的女儿。他十一年间吞并米底、吕底亚和巴比伦，在故乡新建都城帕萨尔加德，前530年在中亚征战时死去，葬在帕萨尔加德一座石砌的小屋形陵墓里。",
