    "life": "约前550—前486年",
    "relation": "波斯国王（前522—前486年）· 居鲁士的女婿",
    "place": "persepolis",
    "bio": "希斯塔斯佩斯之子，曾在冈比西斯身边当持矛侍卫。他杀了居鲁士的小儿子夺位，又娶了居鲁士的两个女儿；定省、定税、修路、铸币，在波斯波利斯修起新宫，前490年派兵渡海征希腊，在马拉松受挫。",
