    "place": "carrhae",
    "bio": "苏伦家族的家主，世代有为安息王加冕的特权。据普鲁塔克，他是安息人里最高大俊美的，却照米底人的打扮涂脸、分头发；不到三十岁就帮奥罗德斯二世复位，带头登城攻下塞琉西亚。卡莱大胜后不久被国王处死。",
