    "en": "Kavad I",
    "life": "约473—531年",
    "relation": "萨珊国王（488—496年、498—531年在位）· 卑路斯之子",
    "place": "ctesiphon",
    "bio": "卑路斯之子，少年时在嚈哒宫廷当过人质。十五岁被大贵族扶上台，借马兹达克派压贵族和祭司，被废后越狱逃往嚈哒，又带嚈哒兵复位。他两度同东罗马开战，晚年清算马兹达克派，临终立第三子库思老为嗣。",
