    "en": "Khosrow I",
    "life": "？—579年",
    "relation": "萨珊国王（531—579年）· 卡瓦德一世的第三子",
    "place": "ctesiphon",
    "bio": "死后得名“不朽的灵魂”（阿努希尔万），生前号称“主持公道者”，伊斯兰时代称“公正者”。他丈量土地、定额收税，扶植德赫干，把全国兵权一分为四；东边联合突厥灭了嚈哒。他一死，大贵族又很快把权力夺了回去。",
