    "place": "ctesiphon",
    "bio": "霍尔木兹四世之子，母亲出自安息旧族伊斯帕赫布丹家。即位前当过高加索阿尔巴尼亚的总督，把格鲁吉亚并成波斯的行省。他号称“得胜者”，娶基督徒希琳为后，偏向一性论派；打到埃及和君士坦丁堡对岸，最后被儿子推翻处死。",
