    "bio": "库思老二世之孙，父亲沙赫里亚尔被叔父卡瓦德二世所杀，他躲在伊斯塔赫尔才活下来，八岁被大族抬上王位，实权在鲁斯塔姆等人手里。他几次遣使到长安求援，唐太宗没有出兵。至今琐罗亚斯德教的历法仍从他即位那年起算。",
