    "bio": "秃头查理时的权臣“毛脚”贝尔纳之子，886年继任奥弗涅伯爵，893年起称阿基坦公爵，地盘从奥弗涅、利穆赞连到欧坦、马孔一带，在布里乌德用自己的名字铸币。910年把克吕尼献给圣彼得。918年死，没有儿子，由外甥继位。",
