    "place": "gr_toul",
    "bio": "原名布鲁诺，生在阿尔萨斯的埃吉斯海姆，父亲是康拉德二世的表兄弟。五岁进图勒的主教学校，1026年替主教带兵随康拉德南征，次年起当了二十多年图勒主教。当教宗后多半在路上开会，1053年打诺曼人兵败被扣，次年4月死在罗马。",
