    "bio": "少年时被送进洛林的穆瓦扬穆捷修道院当修士，与图勒主教布鲁诺交好，随他到罗马。1050年受封西西里大主教，没能赴任，次年改任席尔瓦坎迪达的枢机主教，替教宗执笔、翻译希腊文。1054年出使君士坦丁堡，1061年死在罗马。",
