    "bio": "据李维是牧人出身，后来打猎、当兵。前150年罗马总督加尔巴假意分地、诱杀卢西塔尼亚青壮，他是少数逃出来的人之一；前147年被推为首领，打了八年游击，前140年逼罗马承认他是“罗马人民之友”，次年被收买的亲信刺死。",
