    "life": "约385—418年",
    "relation": "西哥特王（415—418年）",
    "place": "ib_barcino",
    "bio": "415年阿陶尔夫和继位的西格里克相继被部下所杀，哥特人推瓦利亚为王。他想渡海去非洲，船队遇风覆没，只好跟罗马议和：送还皇妹，换来粮食，替罗马打西班牙的汪达尔人和阿兰人。418年落户阿基坦，他随即死去，狄奥多里克一世继位。",
