    "place": "toletum",
    "bio": "莱奥维吉尔德与第一位妻子所生的次子。586年即位，次年改信天主教，589年在第三次托莱多会议上带哥特人和苏维汇人当众弃阿里乌派，接连挫败阿里乌派主教和继母的密谋。601年死在托莱多，儿子即位两年后被篡位者所杀。",
