    "en": "Isidore of Seville",
    "life": "约560—636年",
    "relation": "塞维利亚主教（约600—636年）· 莱安德的弟弟",
    "place": "vg_seville",
    "bio": "生在卡塔赫纳的西班牙罗马人望族，接替哥哥莱安德任塞维利亚主教三十多年。他的《词源》二十卷把古代学问分门别类摘抄下来，不少失传古书靠它留下片段；又写了《哥特史》。633年主持第四次托莱多会议。",
