    "place": "toletum",
    "bio": "哥特贵族，642年年近八十时发动政变，废了少年国王图尔加。据弗雷德加，他杀了两百名大贵族、五百名小贵族，把他们的妻女和家产赏给亲信。649年立儿子雷切斯文特为共治王，又着手编一部两族通用的法典，九十来岁死去。",
