    "place": "ar_medina",
    "bio": "麦加古莱什部哈希姆家族的遗腹子，六岁丧母，先后由祖父和伯父艾布·塔利卜抚养，替人押商队为生，娶了富孀赫底彻。约610年起宣讲独一真主，622年迁麦地那，630年拿下麦加，632年6月在麦地那病逝。",
