    "place": "ar_mecca",
    "bio": "古莱什部阿萨德家族的富孀，自己不出门，雇人押货、按利分成。约595年嫁给替她押货的穆罕默德，二十多年里他没有别的妻子。他宣讲后她第一个信从；抵制哈希姆家族的几年里缺粮，619年去世，那一年被称作“悲伤之年”。",
