    "bio": "多数今人认为他是柏柏尔人，北非总督穆萨的释奴，708年起镇守丹吉尔。711年带七千人渡海，在瓜达莱特打败西哥特王罗德里克，直取都城托莱多；直布罗陀的名字就来自“塔里克山”。714年他和穆萨一同被召回大马士革，再没回来。",
