    "en": "Tiberius Julius Aspurgus",
    "life": "？—37/38年",
    "relation": "博斯普鲁斯国王（约8—37/38年）· 法纳西斯二世的外孙",
    "place": "panticapaeum",
    "bio": "博斯普鲁斯王阿珊德罗斯和女王狄娜米斯之子，母亲是法纳西斯二世的女儿。他得了罗马公民权，取名提比略·尤利乌斯，自称“罗马人之友”；14年才得到奥古斯都和元老院承认。此后到341年，博斯普鲁斯的国王大多出自他这一支。",
