    "place": "es_f_huncourt",
    "bio": "匈人之王。434年与哥哥布列达一同接掌匈人，445年布列达死后独掌大权；连破巴尔干诸城，逼东罗马加倍纳金，451年西征高卢，在卡塔隆平原受阻。453年新婚之夜鼻血倒灌而死，儿子们争分各族，次年帝国瓦解。",
