    "life": "?—602年",
    "relation": "阿瓦尔可汗（562—602年）",
    "place": "es_f_sirmium",
    "bio": "阿瓦尔人的大可汗。被突厥人赶出草原后，先受东罗马雇佣打别的游牧民，568年趁伦巴第人南下占了潘诺尼亚。582年拿下西尔米乌姆，此后年年向东罗马要钱，带着斯拉夫属民劫掠巴尔干；晚年几个儿子死在东罗马军手里，602年去世。",
