    "bio": "945年丈夫伊戈尔因加收贡赋被德列夫利亚人杀死，她替幼子摄政，报仇之后定下贡额和收贡点，是罗斯头一回有记载的定制。950年代到君士坦丁堡见君士坦丁七世，成了罗斯头一个受洗的统治者；969年死在基辅。",
