    "bio": "诺曼底欧特维尔的小骑士坦克雷德之子，外号“吉斯卡尔”意为“狡猾的”。约1047年到南意大利投奔异母兄长，在卡拉布里亚靠劫掠起家。1057年接哥哥当阿普利亚伯爵，1059年受教宗封为公爵。1071年攻下巴里，1076年攻下萨勒诺，1081年起渡海打东罗马，1084年回师解救格雷戈里七世，1085年7月在凯法利尼亚岛病死。",
