    "relation": "教宗（1088—1099年）· 克吕尼的副院长出身",
    "place": "clermont",
    "bio": "原名奥多，香槟地区的骑士之子，在兰斯读书，约1070年入克吕尼，做到副院长；格雷戈里七世召他去罗马，封奥斯蒂亚枢机主教。1088年当选教宗，1095年在克莱蒙号召十字军，1099年7月死在罗马，没等到耶路撒冷陷落的消息。",
