    "bio": "第戎附近方丹领主之子，1113年带着兄弟、亲友三十来人投熙笃，1115年建明谷，当了三十八年院长。他写书挖苦克吕尼的排场，1130年力挺英诺森二世，1146年鼓动第二次十字军；1153年8月死在明谷，1174年封圣。",
