    "bio": "布洛涅伯爵厄斯塔斯二世的幼子，戈弗雷的弟弟，原本学做教士，后来改当骑士。1098年在埃德萨立了头一个十字军国家；1100年哥哥死后南下耶路撒冷，圣诞节在伯利恒加冕。鲍德温靠意大利和北欧的舰队拿下沿海港口，1118年远征埃及时旧伤复发而死，葬在圣墓教堂，挨着戈弗雷。",
