    "place": "rome",
    "bio": "原名彼得·皮耶莱奥尼，罗马银钱世家的次子。在巴黎读书，入克吕尼当修士，被帕斯卡尔二世召回教廷、封为枢机，后出使法兰西、英格兰。1130年被多数枢机选为教宗，占着罗马，给罗杰二世王冠换来支持，各国却多认英诺森二世。1138年1月25日死在罗马，继任的人几个月后就向英诺森低头。",
