    "bio": "红胡子和勃艮第的贝亚特丽丝最小的儿子，生在帕维亚一带，早年当教士，1193年还俗；1195年受封托斯卡纳，因占了教宗的地被塞莱斯廷三世绝罚，1196年接任士瓦本公爵，娶了东罗马皇帝伊萨克二世的女儿伊琳娜。1198年当选国王，内战中渐占上风，1205年在亚琛重新加冕，1208年6月在班贝格被维特尔斯巴赫的奥托刺死，后来侄子腓特烈二世把他改葬施派尔。",
