    "name": "路易六世（胖子）",
    "en": "Louis VI the Fat",
    "life": "1081—1137年",
    "relation": "法兰克人的国王（1108—1137年）· 腓力一世与荷兰的贝尔塔之子",
    "place": "w_saintdenis",
    "bio": "腓力一世长子，少年在圣但尼与苏热同窗，约1098年起代父领兵，1108年继位。在位二十九年，打着护教旗号肃清王领内的强盗男爵，庇护逃难教宗，扶持王领外城市公社，1124年举圣但尼军旗吓退亨利五世，临终替子迎娶埃莉诺。",
