    "place": "c2_fontevraud",
    "bio": "安茹伯爵若弗鲁瓦五世与英王亨利一世之女玛蒂尔达的长子，生于勒芒。1150—1151年接掌诺曼底与安茹，1152年娶刚与法王离婚的阿基坦的埃莉诺得阿基坦，1154年底即位为英王，建立横跨海峡的金雀花帝国。晚年诸子在法王挑拨下屡次反叛，1189年败于腓力二世与儿子理查，病死希农，葬于丰特夫罗。",
